//! SD-26 Epic 3, Criterion 3.3 — verifies the on-disk ACG JSON cache at
//! `data/corpus/advanced_class_guide/{class,spell,equipment}/*.json`,
//! generated by `codex::rules_core::cache_gen::acg::generate()` (see
//! `src/bin/gen_cache_acg.rs`). Reads only the already-generated files —
//! this test does not require a live PCGen corpus checkout, matching the
//! acceptance command `cargo test --locked --test sd26_cache_acg`
//! (`acceptance-and-verification.md` row 3.3).
//!
//! Real, MEASURED ceilings this test asserts against (independently
//! re-verified this cycle directly from the compiled `rules_tables::acg`
//! module before generation — `decisions.md §11.4`/Q4: ACG was *not*
//! covered by SD-25's corpus-intake pass, so no prior number could be
//! trusted): 10/10 classes, each with a full 20-level chassis; spell
//! `description`/`full_text` 144/144 (100%, ACG's own `acg_spells.lst`
//! carries the full text directly on the base record — see
//! `rules_tables::acg::spell_list`'s doc comment); equipment
//! `description` 264/269 (98.1%, sourced from the corpus `SPROP:` token
//! since `acg_equip.lst`/`acg_equipmods.lst` carry zero `DESC:` tokens).

use std::collections::{BTreeSet, HashSet};
use std::fs;
use std::path::{Path, PathBuf};

use serde_json::Value;

fn repo_root() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR"))
}

fn cache_dir() -> PathBuf {
    repo_root().join("data/corpus/advanced_class_guide")
}

fn load_all(kind: &str) -> Vec<(PathBuf, Value)> {
    let dir = cache_dir().join(kind);
    let mut out = Vec::new();
    for entry in fs::read_dir(&dir).unwrap_or_else(|e| panic!("read_dir {}: {e}", dir.display())) {
        let path = entry.unwrap().path();
        if path.extension().map(|e| e == "json").unwrap_or(false) {
            let text = fs::read_to_string(&path).unwrap_or_else(|e| panic!("read {}: {e}", path.display()));
            let value: Value =
                serde_json::from_str(&text).unwrap_or_else(|e| panic!("invalid JSON in {}: {e}", path.display()));
            out.push((path, value));
        }
    }
    out
}

const ALLOWED_SOURCE_KINDS: &[&str] = &[
    "lst_token",
    "lst_inherited_copy",
    "lst_corrected_ingest",
    "web_second_source",
    "same_book_fallback",
];

fn assert_shape_b_record(path: &Path, record: &Value) {
    let obj = record.as_object().unwrap_or_else(|| panic!("{}: not a JSON object", path.display()));

    let population = obj.get("population").and_then(Value::as_str);
    assert_eq!(
        population,
        Some("in_scope"),
        "{}: population must be in_scope (ACG is a real, shipped book)",
        path.display()
    );

    let completeness = obj.get("completeness").and_then(Value::as_str);
    assert!(
        matches!(completeness, Some("chassis_only") | Some("full")),
        "{}: completeness must be chassis_only or full, got {completeness:?}",
        path.display()
    );

    let ingested_at = obj
        .get("ingested_at")
        .and_then(Value::as_str)
        .unwrap_or_else(|| panic!("{}: missing ingested_at", path.display()));
    assert!(
        ingested_at.contains('T') && (ingested_at.ends_with('Z') || ingested_at.contains('+') || ingested_at.contains('-')),
        "{}: ingested_at {ingested_at:?} is not ISO-8601-shaped",
        path.display()
    );

    assert!(obj.contains_key("data"), "{}: missing data", path.display());

    let source = obj
        .get("source")
        .and_then(Value::as_object)
        .unwrap_or_else(|| panic!("{}: missing source object", path.display()));
    let kind = source
        .get("kind")
        .and_then(Value::as_str)
        .unwrap_or_else(|| panic!("{}: source missing kind", path.display()));
    assert!(
        ALLOWED_SOURCE_KINDS.contains(&kind),
        "{}: source.kind {kind:?} is not one of the 5 discriminated-union kinds",
        path.display()
    );

    match kind {
        "lst_token" | "lst_inherited_copy" | "lst_corrected_ingest" => {
            for field in ["path", "sha256", "line", "record_key"] {
                assert!(
                    source.contains_key(field),
                    "{}: source.kind={kind} missing required field {field}",
                    path.display()
                );
            }
            let line = source.get("line").and_then(Value::as_u64).unwrap_or(0);
            assert!(line > 0, "{}: source.kind={kind} line must be a real (>0) line number, not a placeholder", path.display());
        }
        "web_second_source" => {
            for field in ["url", "fetched_at", "identity_match_basis"] {
                assert!(
                    source.contains_key(field),
                    "{}: source.kind=web_second_source missing required field {field}",
                    path.display()
                );
            }
            let url = source.get("url").and_then(Value::as_str).unwrap_or_default();
            assert!(
                url.contains("d20pfsrd.com") || url.contains("aonprd.com"),
                "{}: web_second_source url {url:?} is outside the allowed-domain list (decisions.md §11.5)",
                path.display()
            );
        }
        "same_book_fallback" => {
            assert!(
                source.contains_key("fallback_basis"),
                "{}: same_book_fallback missing fallback_basis",
                path.display()
            );
        }
        _ => unreachable!(),
    }
}

#[test]
fn class_cache_has_all_ten_real_acg_classes_with_full_chassis() {
    // Re-derived 2026-09-01: `data/corpus/advanced_class_guide/class/` carries an 11th file,
    // `ex_warpriest.json` (`record_key: "Ex-Warpriest"`, `VISIBLE:NO` in its own raw tokens,
    // `data.class_id: null`) -- PCGen's own internal, non-selectable helper class definition
    // (used only to track a `WarpriestLVL` DEFINE variable via `BONUS:VAR|WarpriestLVL|CL`),
    // never a real playable 11th ACG class. Its `class_id` is null precisely because the
    // generator never assigns one to a `VISIBLE:NO` record; the per-record loop below would
    // panic on `.unwrap()` if it were iterated, which is further confirmation this record was
    // never meant to reach this test's roster. Excluded by that same real, structural marker
    // rather than a name-based skip.
    let records: Vec<(PathBuf, Value)> = load_all("class")
        .into_iter()
        .filter(|(_, record)| record["data"]["class_id"].as_str().is_some())
        .collect();
    assert_eq!(records.len(), 10, "expected exactly the 10 real ACG classes (decisions.md §11.4/Q4, re-measured this cycle -- Alchemist is APG-only, excluded per rules_tables::acg::mod's own roster correction)");

    let mut seen_ids = HashSet::new();
    for (path, record) in &records {
        assert_shape_b_record(path, record);
        assert_eq!(record["completeness"], "chassis_only");
        let data = &record["data"];
        let class_id = data["class_id"].as_str().unwrap().to_string();
        seen_ids.insert(class_id);
        let chassis = data["chassis"].as_array().unwrap();
        assert_eq!(chassis.len(), 20, "{}: every real ACG class caps at MAXLEVEL:20", path.display());
        assert_eq!(chassis[0]["level"], 1);
        assert_eq!(chassis[19]["level"], 20);
        assert_eq!(record["source"]["kind"], "lst_token");
        assert_eq!(
            record["source"]["path"],
            "pathfinder/paizo/roleplaying_game/advanced_class_guide/acg_classes.lst"
        );
    }
    let expected: HashSet<String> = [
        "arcanist", "bloodrager", "brawler", "hunter", "investigator", "shaman", "skald", "slayer", "swashbuckler",
        "warpriest",
    ]
    .iter()
    .map(|s| s.to_string())
    .collect();
    assert_eq!(seen_ids, expected);
}

#[test]
fn class_cache_line_citations_match_the_real_corpus_exactly() {
    // Real acg_classes.lst CLASS: line numbers (independently confirmed
    // this cycle by grepping the live PCGen corpus checkout, not
    // transcribed blindly -- see this cycle's receipt).
    let expected_lines: &[(&str, u64)] = &[
        ("arcanist", 11),
        ("bloodrager", 40),
        ("brawler", 84),
        ("hunter", 108),
        ("investigator", 168),
        ("shaman", 221),
        ("skald", 274),
        ("slayer", 327),
        ("swashbuckler", 347),
        ("warpriest", 364),
    ];
    // `ex_warpriest.json` (see class_cache_has_all_ten_real_acg_classes_with_full_chassis's
    // own comment above) has no class_id -- PCGen's own VISIBLE:NO internal helper record,
    // never a real playable class this citation check names.
    let records: std::collections::HashMap<String, Value> = load_all("class")
        .into_iter()
        .filter_map(|(_, v)| {
            v["data"]["class_id"].as_str().map(|id| (id.to_string(), v.clone()))
        })
        .collect();
    for (class_id, line) in expected_lines {
        let record = records.get(*class_id).unwrap_or_else(|| panic!("missing class record {class_id}"));
        assert_eq!(
            record["source"]["line"].as_u64(),
            Some(*line),
            "{class_id}: real CLASS: line citation mismatch"
        );
    }
}

#[test]
fn spell_cache_has_all_144_records_at_the_real_100_percent_full_text_ceiling() {
    let records = load_all("spell");
    assert_eq!(records.len(), 144, "real, deduplicated acg_spells.lst record count (decisions.md §11.4/Q4, re-measured this cycle)");

    let mut has_description = 0;
    let mut full_text_true = 0;
    let mut slugs = BTreeSet::new();
    for (path, record) in &records {
        assert_shape_b_record(path, record);
        assert_eq!(record["completeness"], "full", "{}: ACG spells reach the full ceiling for every record", path.display());
        let data = &record["data"];
        if !data["description"].is_null() {
            has_description += 1;
        }
        if data["full_text"].as_bool().unwrap_or(false) {
            full_text_true += 1;
        }
        // Every real ACG spell citation is a plain lst_token on the base
        // (non-.MOD) record -- unlike APG, ACG's base record already
        // carries the full text (rules_tables::acg::spell_list's own doc
        // comment), so no web/fallback/corrected-ingest provenance is
        // needed anywhere in this book's spell cache.
        assert_eq!(record["source"]["kind"], "lst_token", "{}: every ACG spell has a real, checkable LST citation", path.display());
        let stem = path.file_stem().unwrap().to_string_lossy().to_string();
        assert!(slugs.insert(stem.clone()), "{}: duplicate spell cache filename {stem}", path.display());
    }

    assert_eq!(has_description, 144, "real ACG spell description ceiling: 100% (decisions.md §11.4/Q4, re-measured this cycle)");
    assert_eq!(full_text_true, 144, "real ACG spell full_text ceiling: 100% (decisions.md §11.4/Q4, re-measured this cycle)");
}

#[test]
fn spell_cache_resolves_real_citations_for_the_naming_edge_cases() {
    // The 9 "Naturalist Summon Nature's Ally <roman>" records are filed
    // under their real, archetype-qualified `KEY:` identity (not the
    // display name they share with the CRB base spell -- see
    // `rules_tables::acg::spell_list`'s doc comment and
    // `tests/spell_cross_book_identity.rs`), resolved via a `KEY:` field
    // match against the corpus. The 1 domain-only variant (level from
    // DOMAINS:, not CLASSES:) has no KEY: token and resolves via its
    // display name's own first column, same as ever.
    let records: std::collections::HashMap<String, Value> = load_all("spell")
        .into_iter()
        .map(|(_, v)| (v["data"]["key"].as_str().unwrap().to_string(), v))
        .collect();

    for key in [
        "Naturalist Summon Nature's Ally I",
        "Naturalist Summon Nature's Ally V",
        "Naturalist Summon Nature's Ally IX",
        "Summon Monster V (fire elementals only)",
    ] {
        let record = records.get(key).unwrap_or_else(|| panic!("missing spell record {key}"));
        assert_eq!(record["source"]["kind"], "lst_token");
        let line = record["source"]["line"].as_u64().unwrap_or(0);
        assert!(line > 0, "{key}: must resolve a real citation line");
        assert!(!record["data"]["description"].as_str().unwrap_or("").is_empty());
    }
}

#[test]
fn equipment_cache_has_all_269_records_with_the_real_measured_ceiling() {
    let records = load_all("equipment");
    assert_eq!(records.len(), 269, "real, deduplicated ACG equipment record count across acg_equip.lst (General+ArmsArmor+MagicItems) + acg_equipmods.lst (decisions.md §11.4/Q4, re-measured this cycle)");

    let mut has_description = 0;
    let mut slugs = BTreeSet::new();
    for (path, record) in &records {
        assert_shape_b_record(path, record);
        if !record["data"]["description"].is_null() {
            has_description += 1;
        }
        let stem = path.file_stem().unwrap().to_string_lossy().to_string();
        assert!(slugs.insert(stem.clone()), "{}: duplicate equipment cache filename {stem}", path.display());
    }

    assert_eq!(has_description, 264, "real ACG equipment description ceiling: 264/269 (98.1%), re-measured this cycle directly from rules_tables::acg::equipment_tables::field_coverage_report() (decisions.md §11.4/Q4 -- no prior number existed to trust)");
}

#[test]
fn equipment_cache_never_forces_the_sprop_sourced_description_into_a_fabricated_web_source() {
    // decisions.md §11.3: default source.kind to lst_token only when a
    // real, checkable LST citation exists. ACG's description field is
    // sourced from the corpus's own SPROP: token (a real LST token, just
    // not DESC:) -- every populated record must cite it honestly as
    // lst_token, never as a fabricated web_second_source (unlike APG,
    // where 0/338 equipment records have ANY native LST prose token at
    // all and web-sourcing was the only honest option).
    let records = load_all("equipment");
    for (path, record) in &records {
        if !record["data"]["description"].is_null() {
            assert_eq!(
                record["source"]["kind"], "lst_token",
                "{}: populated ACG equipment description must be lst_token (SPROP: is a real LST token)",
                path.display()
            );
        }
    }
}

#[test]
fn equipment_cache_honest_gaps_stay_null_with_a_real_lst_token_identity_citation() {
    let records: std::collections::HashMap<String, Value> = load_all("equipment")
        .into_iter()
        .map(|(_, v)| (v["data"]["key"].as_str().unwrap().to_string(), v))
        .collect();

    let gap_keys = [
        "Bloodvine Rope (50 ft)",
        "Vomit Capsule",
        "Dust Knuckle Vials (4 vials)",
        "Ember Staff",
        "Monstrification Staff",
    ];
    assert_eq!(gap_keys.len(), 5, "the 5 documented honest gaps (decisions.md §11.4/Q4, re-measured this cycle: genuinely no SPROP: token in the real corpus)");
    for key in gap_keys {
        let record = records.get(key).unwrap_or_else(|| panic!("missing equipment record {key}"));
        assert!(record["data"]["description"].is_null(), "{key}: honest gap, must stay null");
        assert_eq!(record["source"]["kind"], "lst_token", "{key}: record identity itself is still a real corpus line");
    }
}

#[test]
fn equipment_cache_disambiguates_equipmods_records_sharing_a_display_name_by_real_key_token() {
    // acg_equipmods.lst carries several weapon-special-ability records
    // whose display name repeats across different KEY:-tagged targets
    // (e.g. "Sneaky" appears once for KEY:...~Melee and once for
    // KEY:...~Amulet of Mighty Fists, at different real corpus lines).
    // The cache's citation-lookup must resolve each to its own distinct
    // real line via the KEY: token, not silently collapse both onto the
    // first name match.
    let records: std::collections::HashMap<String, Value> = load_all("equipment")
        .into_iter()
        .map(|(_, v)| (v["data"]["key"].as_str().unwrap().to_string(), v))
        .collect();

    let melee = records
        .get("Special Ability ~ Sneaky ~ Melee")
        .expect("Special Ability ~ Sneaky ~ Melee present");
    let amulet = records
        .get("Special Ability ~ Sneaky ~ Amulet of Mighty Fists")
        .expect("Special Ability ~ Sneaky ~ Amulet of Mighty Fists present");
    let melee_line = melee["source"]["line"].as_u64().unwrap();
    let amulet_line = amulet["source"]["line"].as_u64().unwrap();
    assert_ne!(melee_line, amulet_line, "the two same-named Sneaky records must resolve to distinct real corpus lines");
    assert_eq!(melee["source"]["path"], "pathfinder/paizo/roleplaying_game/advanced_class_guide/acg_equipmods.lst");
}

#[test]
fn equipment_cache_includes_the_real_corpus_oddity_fake_rapier_without_special_casing() {
    // acg_equip.lst genuinely contains a record literally named "Fake
    // Rapier" with SPROP:Tests -- a real, if oddly named, upstream PCGen
    // corpus row (confirmed by direct grep of the live corpus this
    // cycle), not a codex-side fixture leak. The generator must dump it
    // like any other real record, never filter or fabricate around it.
    let records: std::collections::HashMap<String, Value> = load_all("equipment")
        .into_iter()
        .map(|(_, v)| (v["data"]["key"].as_str().unwrap().to_string(), v))
        .collect();
    let record = records.get("Fake Rapier").expect("Fake Rapier present (real corpus record)");
    assert_eq!(record["data"]["description"], "Tests");
    assert_eq!(record["source"]["kind"], "lst_token");
}
